#!/usr/bin/env bash
#
# The load Blaze Pulse measures.
#
# The load is generated by a separate process: this script drives `oha` or
# `wrk` against the dashboard's `/ping` route, and posts what was measured
# back to the server, which publishes it to the dashboard.
#
#   bench/load.sh [port] [duration] [connections]
#
# The duration is what `oha` and `wrk` take: "10s", "2m" or a number of
# seconds.

set -euo pipefail

port="${1:-8080}"
duration="${2:-10s}"
connections="${3:-50}"
host="127.0.0.1"
base="http://${host}:${port}"

# The tool that generates the load. `oha` is asked for first because it
# reports what it measured in a form that can be read back; `wrk` is the
# alternative, and its report is read out of the text it writes.
tool="${PULSE_TOOL:-}"

if [ -z "${tool}" ]; then
	if command -v oha >/dev/null 2>&1; then
		tool="oha"
	elif command -v wrk >/dev/null 2>&1; then
		tool="wrk"
	else
		echo "blaze pulse: neither oha nor wrk is installed." >&2
		echo "  install one of them: https://github.com/hatoo/oha or https://github.com/wg/wrk" >&2
		exit 1
	fi
fi

if ! command -v "${tool}" >/dev/null 2>&1; then
	echo "blaze pulse: ${tool} is not installed." >&2
	exit 1
fi

if ! command -v curl >/dev/null 2>&1; then
	echo "blaze pulse: curl is not installed, and the server cannot be told about the run." >&2
	exit 1
fi

# The window the server measures in is opened before the load starts and
# closed after it ends, so that the numbers the dashboard shows are the ones of
# this run and not of everything the server has ever answered.
curl -fsS -X POST "${base}/api/bench/start" >/dev/null

# The length of the run in milliseconds, which the report carries: the tools
# do not all say how long they ran for.
case "${duration}" in
*s) seconds="${duration%s}" ;;
*m) seconds=$((${duration%m} * 60)) ;;
*) seconds="${duration}" ;;
esac
duration_ms=$((${seconds} * 1000))

echo "blaze pulse: ${tool} is loading ${base}/ping for ${duration} with ${connections} connections"

status=0
case "${tool}" in
oha)
	# The JSON is asked for with --output-format: --output names the file the
	# results are written to, and a file named "json" is not what a dashboard
	# wants.
	output="$(oha --output-format json -c "${connections}" -z "${duration}" "${base}/ping" 2>/dev/null)" || status=$?
	;;
wrk)
	output="$(wrk -t4 -c "${connections}" -d "${duration}" --latency "${base}/ping" 2>/dev/null)" || status=$?
	;;
*)
	echo "blaze pulse: ${tool} is not a tool this script knows." >&2
	exit 1
	;;
esac

if [ "${status}" -ne 0 ]; then
	echo "blaze pulse: ${tool} failed (status ${status}); the run is not reported." >&2
	curl -fsS -X POST "${base}/api/bench/stop" >/dev/null || true
	exit "${status}"
fi

# The report is written out in the one shape the server reads, whatever the
# tool was: the rate, the percentiles, the count and what went wrong.
if [ "${tool}" = "oha" ]; then
	if ! command -v jq >/dev/null 2>&1; then
		echo "blaze pulse: jq is needed to read what oha measured." >&2
		curl -fsS -X POST "${base}/api/bench/stop" >/dev/null || true
		exit 1
	fi
	# What oha measures is read out of the "metrics" it writes, which are the
	# statistics meant for a machine: the rate, and the latency in
	# milliseconds. The count of the requests is the sum of the counts of the
	# status codes, and the errors are what never got an answer at all.
	report="$(printf '%s' "${output}" | jq -c '{
		tool: "oha",
		rps: (.metrics.requests_per_sec // .summary.requestsPerSec // .rps.mean // 0),
		total: (([.statusCodeDistribution[]?] | add) // 0),
		errors: (([.errorDistribution[]?] | add) // 0),
		mean: (.metrics.latency_ms.mean // 0),
		p50: (.metrics.latency_ms.p50 // 0),
		p95: (.metrics.latency_ms.p95 // 0),
		p99: (.metrics.latency_ms.p99 // 0),
		durationMs: '"${duration_ms}"'
	}')"
else
	# What wrk writes is text, and the numbers are read out of the lines it
	# writes: the rate from the line it ends with, the count from the line
	# that says how many requests it made, and the percentiles from the
	# distribution it prints.
	report="$(printf '%s' "${output}" | awk -v duration_ms="${duration_ms}" '
		function number(text,    value) {
			value = text
			sub(/[^0-9.]/, "", value)
			return value + 0
		}
		/Requests\/sec:/ { rps = number($2) }
		/requests in/ { total = number($1) }
		/^[[:space:]]*Latency[[:space:]]+[0-9.]/ { mean = number($2) }
		/^[[:space:]]*[0-9.]+%[[:space:]]/ {
			percent = number($1)
			latency = number($2)
			if (percent >= 50 && percent <= 50.5 && p50 == 0) { p50 = latency }
			if (percent >= 95 && percent <= 95.5 && p95 == 0) { p95 = latency }
			if (percent >= 99 && percent <= 99.5 && p99 == 0) { p99 = latency }
		}
		END {
			printf "{\"tool\":\"wrk\",\"rps\":%f,\"total\":%d,\"errors\":%d,\"mean\":%f,\"p50\":%f,\"p95\":%f,\"p99\":%f,\"durationMs\":%d}",
				rps + 0, total + 0, 0, mean + 0, p50 + 0, p95 + 0, p99 + 0, duration_ms + 0
		}
	')"
fi

if [ -z "${report}" ]; then
	echo "blaze pulse: ${tool} measured nothing that could be read; the run is not reported." >&2
	curl -fsS -X POST "${base}/api/bench/stop" >/dev/null || true
	exit 1
fi

curl -fsS -X POST -H "content-type: application/json" --data "${report}" "${base}/api/bench/result" >/dev/null
curl -fsS -X POST "${base}/api/bench/stop" >/dev/null

echo "blaze pulse: reported ${report}"
